// Some portions generated by Claude

// @ts-check
const { test, expect } = require('@playwright/test');
const {
    deleteRepository,
    memoryRepositoryConfiguration,
    openQueryPage,
    serverBaseUrl,
    setQueryEditor,
    uniqueRepositoryId
} = require('./workbench-test-helpers.js');

const REPOSITORY_ID = uniqueRepositoryId('workbench-explain-timeout');
const REPOSITORY_URL = `${serverBaseUrl()}/repositories/${encodeURIComponent(REPOSITORY_ID)}`;
const QUERY_TIMEOUT_SECONDS = 1;
// 400^3 = 64,000,000 rows: far more than the server runs through in the one second it may spend on the explanation.
const VALUES = Array.from({ length: 400 }, (_, index) => String(index)).join(' ');
const CARTESIAN_QUERY = `SELECT * WHERE { VALUES ?a { ${VALUES} } VALUES ?b { ${VALUES} } VALUES ?c { ${VALUES} } }`;

test.beforeAll(async ({ request }) => {
    const created = await request.put(REPOSITORY_URL, {
        headers: { 'Content-Type': 'text/turtle' },
        data: memoryRepositoryConfiguration(REPOSITORY_ID, 'Workbench explain timeout fixture')
    });
    expect([200, 201, 204]).toContain(created.status());
});

test.afterAll(async ({ request }) => {
    await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

test('a stale explanation refreshes from its status, and a timed-out one keeps its partial plan', async ({ page }) => {
    test.setTimeout(90000);
    await openQueryPage(page, REPOSITORY_ID);
    await page.locator('#query-options-toggle').click();
    await page.locator('#query-timeout').fill(String(QUERY_TIMEOUT_SECONDS));
    await setQueryEditor(page, CARTESIAN_QUERY);

    const status = page.locator('#query-explanation-status');
    const explanation = page.locator('#query-explanation');
    const timing = page.locator('#query-explanation-timing');
    await page.locator('#explain-trigger').click();
    await expect(explanation).toContainText('BindingSetAssignment');
    await expect(timing).toHaveText(/^Explained in [\d,]+ ms$/);
    await expect(status).not.toHaveClass(/query-explanation-status--visible/);

    // Running the query for the Executed plan takes longer than the timeout.
    await page.locator('#explain-level').selectOption('Executed');
    const refresh = status.getByRole('button', { name: 'Explanation is stale. Click here to refresh.' });
    await expect(refresh).toBeVisible();
    await refresh.click();
    await expect(timing).toHaveText(/^Explaining… \d+\.\d s$/);

    await expect(status).toHaveClass(/query-explanation-status--warning/, { timeout: 30000 });
    await expect(timing).toHaveText(/^Explained in [\d,]+ ms$/);
    await expect(status).toContainText('this plan is incomplete');
    await expect(explanation).toContainText('Timed out while retrieving explanation');
    await expect(explanation).toContainText('resultSizeActual=');
    await expect(page.locator('#queryString\\.errors')).toHaveText('');
});
